317	     * @param value the name to encode, may be {@code null}
318	     * @return the four-character Soundex code, or the empty string when there are no letters
319	     */
320	    public static String soundex(String value) {
321	        if (value == null) {
322	            return "";
323	        }
324	        StringBuilder letters = new StringBuilder();
325	        for (int i = 0; i < value.length(); i++) {
326	            char c = value.charAt(i);
327	            if (Character.isLetter(c)) {
328	                letters.append(Character.toUpperCase(c));
329	            }
330	        }
331	        if (letters.length() == 0) {
332	            return "";
333	        }
334	        StringBuilder code = new StringBuilder();
335	        code.append(letters.charAt(0));
336	        char prev = soundexDigit(letters.charAt(0));
337	        for (int i = 1; i < letters.length() && code.length() < 4; i++) {
338	            char c = letters.charAt(i);
339	            if (c == 'H' || c == 'W') {
340	                // Transparent: keep the previous code so consonants either side stay adjacent.
341	                continue;
342	            }
343	            char digit = soundexDigit(c);
344	            if (digit != '0' && digit != prev) {
345	                code.append(digit);
346	            }
347	            prev = digit;
348	        }
349	        while (code.length() < 4) {
