419	     */
420	    public Pet getPet(String name, boolean ignoreNew) {
421	        name = name.toLowerCase();
422	        for (Pet pet : getPetsInternal()) {
423	            if (!ignoreNew || !pet.isNew()) {
424	                String compName = pet.getName();
425	                compName = compName.toLowerCase();
426	                if (compName.equals(name)) {
427	                    return pet;
428	                }
429	            }
430	        }
431	        return null;
432	    }
