440	        return new ToStringCreator(this)
441	
442	            .append("id", this.getId())
443	            .append("new", this.isNew())
444	            .append("lastName", this.getLastName())
445	            .append("firstName", this.getFirstName())
446	            .append("address", this.address)
447	            .append("city", this.city)
448	            .append("telephone", this.telephone)
449	            .toString();
450	    }
451	}
