82	     * after the '@', compared case-insensitively) is listed here is rejected with 400 Bad Request.
83	     */
84	    private static final java.util.Set<String> DISPOSABLE_EMAIL_DOMAINS = java.util.Set.of(
85	        "mailinator.com",
86	        "tempmail.com",
87	        "guerrillamail.com");
88	
89	    /** Default country code assumed for national numbers that carry no explicit '+' prefix. */
90	    private static final String DEFAULT_COUNTRY_CODE = "61";
91	
92	    /** Maximum number of owners a single city may contain; a create is rejected once it is reached. */
93	    private static final int MAX_OWNERS_PER_CITY = 50;
94	
95	    /** Owner count in a city at or above which a create is flagged as approaching the capacity limit. */
96	    private static final int CAPACITY_WARNING_THRESHOLD = 40;
97	
98	    /** Maximum number of owners that may be registered on a single day; a create is rejected once it is reached. */
99	    private static final int MAX_OWNERS_PER_DAY = 100;
100	
101	    /** Once more than this many owners have already been created on a day, a create carries a bulk-signup warning. */
102	    private static final int BULK_SIGNUP_WARNING_THRESHOLD = 80;
103	
104	    /** Fixed public-holiday calendar: a registration date landing on any of these is rolled forward past it. */
105	    private static final java.util.Set<LocalDate> PUBLIC_HOLIDAYS = java.util.Set.of(
106	        LocalDate.of(2026, 1, 1),
107	        LocalDate.of(2026, 1, 26),
108	        LocalDate.of(2026, 4, 25),
109	        LocalDate.of(2026, 12, 25),
110	        LocalDate.of(2026, 12, 28));
111	
112	    /** Separators (spaces, dashes and brackets) stripped from a telephone before parsing. */
113	    private static final Pattern TELEPHONE_SEPARATORS = Pattern.compile("[\\s()\\[\\]-]");
114	
115	    /** A valid E.164 body: a leading '+' followed by 8 to 15 digits. */
116	    private static final Pattern E164_PATTERN = Pattern.compile("^\\+[0-9]{8,15}$");
117	
118	    /**
119	     * Country calling codes with a fixed national-number length. An E.164 number whose country code
120	     * is listed here must carry exactly the required number of national digits, otherwise it is
121	     * rejected ({@code +61} requires 9 national digits, {@code +1} requires 10). Ordered so that a
122	     * longer prefix is matched before a shorter one (e.g. {@code 61} before {@code 1}).
123	     */
124	    private static final Map<String, Integer> COUNTRY_NATIONAL_LENGTH = Map.of(
125	        "61", 9,
126	        "1", 10);
127	
128	    /** Common street-type abbreviations expanded (on upper-cased tokens) during address normalization. */
129	    private static final Map<String, String> ADDRESS_ABBREVIATIONS = Map.of(
130	        "ST", "STREET",
131	        "RD", "ROAD",
132	        "AVE", "AVENUE");
133	
134	    /** A well-formed postcode: exactly four digits. */
135	    private static final Pattern POSTCODE_PATTERN = Pattern.compile("^[0-9]{4}$");
136	
137	    /** City to canonical region for the fixed city-to-region table (cities not listed have no region). */
138	    private static final Map<String, String> CITY_REGION = Map.of(
139	        "Sydney", "NSW",
140	        "Melbourne", "VIC",
141	        "Brisbane", "QLD");
142	
143	    /** Region to its inclusive 4-digit postcode range {low, high}. */
144	    private static final Map<String, int[]> REGION_POSTCODE_RANGE = Map.of(
145	        "NSW", new int[] {2000, 2099},
146	        "VIC", new int[] {3000, 3099},
147	        "QLD", new int[] {4000, 4099});
