149	    /** Dedicated audit logger; a create side-effect is recorded here on success. */
150	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
151	
152	    /**
153	     * Monotonically increasing sequence number stamped onto each structured {@code OWNER_CREATED}
154	     * audit event, so successive creates carry strictly increasing {@code seq} values across the
155	     * whole application.
156	     */
157	    private static final java.util.concurrent.atomic.AtomicLong AUDIT_EVENT_SEQ =
158	        new java.util.concurrent.atomic.AtomicLong();
