213	        Owner owner = this.clinicService.findOwnerById(ownerId);
214	        if (owner == null) {
215	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
216	        }
217	        populateHouseholdSize(owner);
218	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
219	        applyHouseholdMembershipCap(owner, ownerDto);
220	        return new ResponseEntity<>(ownerDto, HttpStatus.OK);
