504	    /**
505	     * Cap the owner's membership level so it never exceeds one above the current maximum membership
506	     * level among the owner's household members (the other non-deleted owners sharing this owner's
507	     * {@code householdId}). When the household has no other member, no cap applies and the level is
508	     * left untouched. Any reduction is written back onto the given dto.
509	     *
510	     * @param owner    the owner whose household members bound the level (excluded from its own household)
511	     * @param ownerDto the mapped dto whose {@code membershipLevel} is capped in place
512	     */
513	    private void applyHouseholdMembershipCap(Owner owner, OwnerDto ownerDto) {
514	        String householdId = owner.getHouseholdId();
515	        if (!StringUtils.hasText(householdId) || ownerDto.getMembershipLevel() == null) {
516	            return;
517	        }
518	        Integer maxMemberLevel = this.clinicService.findAllOwners().stream()
519	            .filter(existing -> !existing.isDeleted())
520	            .filter(existing -> householdId.equals(existing.getHouseholdId()))
521	            .filter(existing -> !java.util.Objects.equals(existing.getId(), owner.getId()))
522	            .map(this::membershipLevelOf)
523	            .max(Integer::compareTo)
524	            .orElse(null);
525	        if (maxMemberLevel != null && ownerDto.getMembershipLevel() > maxMemberLevel + 1) {
526	            ownerDto.setMembershipLevel(maxMemberLevel + 1);
527	        }
528	    }
