543	    /**
544	     * Generate a customer code formatted {@code <REGION>-<HASH8>}, where {@code REGION} is the region
545	     * code derived from the owner's identity (postcode range first, then the city-to-region table,
546	     * otherwise {@code UNKNOWN}) and {@code HASH8} is the first eight upper-case hex characters of the
547	     * SHA-256 digest of {@code normalizedTelephone + lastName} (e.g. {@code NSW-1A2B3C4D}). There is no
548	     * longer any per-city sequence number.
549	     *
550	     * @param owner the owner whose (already-normalized) telephone, last name, postcode and city are read
551	     * @return the generated (collision-free) customer code
552	     */
553	    private String generateCustomerCode(Owner owner) {
554	        String region = deriveRegion(owner.getPostcode(), owner.getCity());
555	        String hash8 = shortSha256Hex(owner.getTelephone() + owner.getLastName(), 8);
556	        String baseCode = region + "-" + hash8;
557	        return deduplicateCustomerCode(baseCode);
558	    }
559	
560	    /**
561	     * Return a customer code that does not collide with any existing owner's customer code. When the
562	     * given base code is already unique it is returned unchanged; otherwise {@code -<n>} is appended
563	     * with the smallest {@code n} of 2 or more that makes the result unique (e.g. {@code NSW-1A2B3C4D},
564	     * then {@code NSW-1A2B3C4D-2}, {@code NSW-1A2B3C4D-3}, ...). The incoming owner is not yet
565	     * persisted, so it never counts as a collision with itself.
566	     *
567	     * @param baseCode the computed {@code <REGION>-<HASH8>} customer code
568	     * @return the de-duplicated customer code
569	     */
570	    private String deduplicateCustomerCode(String baseCode) {
571	        java.util.Set<String> existingCodes = this.clinicService.findAllOwners().stream()
572	            .map(Owner::getCustomerCode)
573	            .filter(java.util.Objects::nonNull)
574	            .collect(java.util.stream.Collectors.toSet());
575	        if (!existingCodes.contains(baseCode)) {
576	            return baseCode;
577	        }
578	        int n = 2;
579	        String candidate = baseCode + "-" + n;
580	        while (existingCodes.contains(candidate)) {
581	            n++;
582	            candidate = baseCode + "-" + n;
583	        }
584	        return candidate;
585	    }
