587	    /**
588	     * Derive the region code for an owner's identity. The postcode is preferred: when present and it
589	     * falls within a known region's inclusive 4-digit range (NSW 2000-2099, VIC 3000-3099,
590	     * QLD 4000-4099) that region is returned. Otherwise fall back to the pinned city-to-region table
591	     * (Sydney->NSW, Melbourne->VIC, Brisbane->QLD), and finally {@code UNKNOWN} for a city with no
592	     * known region.
593	     *
594	     * @param postcode the owner's postcode, may be {@code null}
595	     * @param city     the owner's city
596	     * @return the derived region code
597	     */
598	    private String deriveRegion(String postcode, String city) {
599	        if (postcode != null && POSTCODE_PATTERN.matcher(postcode).matches()) {
600	            int value = Integer.parseInt(postcode);
601	            for (Map.Entry<String, int[]> entry : REGION_POSTCODE_RANGE.entrySet()) {
602	                int[] range = entry.getValue();
603	                if (value >= range[0] && value <= range[1]) {
604	                    return entry.getKey();
605	                }
606	            }
607	        }
608	        String region = CITY_REGION.get(city);
609	        return region != null ? region : "UNKNOWN";
610	    }
