612	    /**
613	     * Return the first {@code length} upper-case hex characters of the SHA-256 digest of the UTF-8
614	     * bytes of {@code input}.
615	     *
616	     * @param input  the value to digest
617	     * @param length the number of leading hex characters to return
618	     * @return the truncated upper-case hex digest
619	     */
620	    private String shortSha256Hex(String input, int length) {
621	        try {
622	            byte[] digest = MessageDigest.getInstance("SHA-256")
623	                .digest(input.getBytes(StandardCharsets.UTF_8));
624	            StringBuilder sb = new StringBuilder(digest.length * 2);
625	            for (byte b : digest) {
626	                sb.append(String.format("%02x", b));
627	            }
628	            return sb.substring(0, length).toUpperCase(Locale.ROOT);
629	        } catch (java.security.NoSuchAlgorithmException e) {
630	            throw new IllegalStateException("SHA-256 not available", e);
631	        }
632	    }
