634	    /**
635	     * Roll a registration date forward onto a business day: a Saturday, Sunday or listed public
636	     * holiday is advanced day-by-day until it lands on the next non-holiday weekday, while a date
637	     * that is already a non-holiday weekday is returned unchanged. This is the effective registration
638	     * date that is stored, returned and used for every value derived from it.
639	     *
640	     * @param date the effective registration date (supplied or defaulted)
641	     * @return the same date when it is a non-holiday weekday, otherwise the next non-holiday business day
642	     */
643	    private LocalDate rollToBusinessDay(LocalDate date) {
644	        while (!isBusinessDay(date)) {
645	            date = date.plusDays(1);
646	        }
647	        return date;
648	    }
