650	    /**
651	     * A business day is a weekday (Monday to Friday) that is not a listed public holiday.
652	     *
653	     * @param date the date to test
654	     * @return {@code true} when the date is a non-holiday weekday
655	     */
656	    private boolean isBusinessDay(LocalDate date) {
657	        DayOfWeek dayOfWeek = date.getDayOfWeek();
658	        if (dayOfWeek == DayOfWeek.SATURDAY || dayOfWeek == DayOfWeek.SUNDAY) {
659	            return false;
660	        }
661	        return !PUBLIC_HOLIDAYS.contains(date);
662	    }
