736	    /**
737	     * Find the existing owner the given (not-yet-persisted) owner is a soft duplicate of: one that
738	     * shares the owner's {@code soundex(lastName)} and postcode while carrying a DIFFERENT identity
739	     * key. A blank postcode never soft-matches (postcode is required for the match). When several
740	     * owners match, the one with the lowest id is returned so the result is deterministic;
741	     * {@code null} when there is no soft match.
742	     *
743	     * @param owner the incoming owner (with normalized telephone, email and last name resolved)
744	     * @return the lowest-id matching existing owner, or {@code null} when none matches
745	     */
746	    private Owner findPossibleDuplicate(Owner owner) {
747	        if (!StringUtils.hasText(owner.getPostcode())) {
748	            return null;
749	        }
750	        String soundex = Owner.soundex(owner.getLastName());
751	        String identityKey = owner.getIdentityKey();
752	        return this.clinicService.findAllOwners().stream()
753	            .filter(existing -> Owner.soundex(existing.getLastName()).equals(soundex)
754	                && owner.getPostcode().equals(existing.getPostcode())
755	                && !identityKey.equals(existing.getIdentityKey()))
756	            .min(java.util.Comparator.comparing(Owner::getId))
757	            .orElse(null);
758	    }
