761	     * Generate the deterministic household identifier for the given last name and postcode. The value
762	     * is derived from the normalized (case-insensitive, whitespace-collapsed) last name and the
763	     * postcode, so every owner with the same last name and postcode resolves to the same identifier
764	     * automatically. It is the first 12 upper-case hex characters of the SHA-256 digest of
765	     * {@code <normalizedLastName>|<postcode>} (an absent postcode contributes the empty string).
766	     *
767	     * @param lastName the owner's last name
768	     * @param postcode the owner's postcode, may be {@code null}
769	     * @return the deterministic household identifier
770	     */
771	    private String generateHouseholdId(String lastName, String postcode) {
772	        String key = normalizeForComparison(lastName) + "|" + (postcode == null ? "" : postcode);
773	        return shortSha256Hex(key, 12);
