776	    /**
777	     * Normalize an owner address for storage: trim and collapse every internal run of whitespace to a
778	     * single space, upper-case the result and expand common street-type abbreviations token by token
779	     * ({@code ST -> STREET}, {@code RD -> ROAD}, {@code AVE -> AVENUE}). A {@code null} value normalizes
780	     * to the empty string. The result is the canonical form that is stored, returned and used for every
781	     * address comparison (household duplicate detection and the shared household id).
782	     *
783	     * @param address the raw address, may be {@code null}
784	     * @return the normalized address
785	     */
786	    private String normalizeAddress(String address) {
787	        if (address == null) {
788	            return "";
789	        }
790	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
791	        if (collapsed.isEmpty()) {
792	            return "";
793	        }
794	        String[] tokens = collapsed.split(" ");
795	        StringBuilder sb = new StringBuilder(collapsed.length());
796	        for (int i = 0; i < tokens.length; i++) {
797	            if (i > 0) {
798	                sb.append(' ');
799	            }
800	            sb.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
801	        }
802	        return sb.toString();
803	    }
