805	    /**
806	     * Normalize a value for identity comparison: trim, collapse every internal run of whitespace to a
807	     * single space and lower-case the result. A {@code null} value normalizes to the empty string.
808	     *
809	     * @param value the raw value, may be {@code null}
810	     * @return the normalized value
811	     */
812	    private String normalizeForComparison(String value) {
813	        if (value == null) {
814	            return "";
815	        }
816	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
817	    }
