819	    /**
820	     * Normalize an optional owner email address. A blank/absent value is treated as "not provided"
821	     * and returns {@code null}. When present, the value must be a syntactically valid address; if it
822	     * is not, an {@link InvalidRequestException} is thrown (mapped to 400 Bad Request). A valid value
823	     * is returned lower-cased.
824	     *
825	     * @param email the raw email from the request payload, may be {@code null}
826	     * @return the lower-cased email, or {@code null} when none was provided
827	     */
828	    private String normalizeEmail(String email) {
829	        if (!StringUtils.hasText(email)) {
830	            return null;
831	        }
832	        if (!EMAIL_PATTERN.matcher(email).matches()) {
833	            throw new InvalidRequestException(List.of("email"));
834	        }
835	        String lowerCased = email.toLowerCase(Locale.ROOT);
836	        // Reject an address whose domain is on the disposable-domain blocklist.
837	        String domain = lowerCased.substring(lowerCased.indexOf('@') + 1);
838	        if (DISPOSABLE_EMAIL_DOMAINS.contains(domain)) {
839	            throw new InvalidRequestException(List.of("email"));
840	        }
841	        return lowerCased;
842	    }
