844	    /**
845	     * Validate an optional owner postcode. A blank/absent value is treated as "not provided" and
846	     * passes (postcode is optional). When present it must be exactly four digits, and when the owner's
847	     * city has a known region (Sydney->NSW, Melbourne->VIC, Brisbane->QLD) the postcode must fall within
848	     * that region's inclusive range (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099). A city with no known
849	     * region accepts any 4-digit postcode. A violation throws an {@link InvalidRequestException} (mapped
850	     * to 400 Bad Request).
851	     *
852	     * @param city     the owner's city (used to resolve the region)
853	     * @param postcode the raw postcode from the request payload, may be {@code null}
854	     */
855	    private void validatePostcode(String city, String postcode) {
856	        if (!StringUtils.hasText(postcode)) {
857	            return;
858	        }
859	        if (!POSTCODE_PATTERN.matcher(postcode).matches()) {
860	            throw new InvalidRequestException(List.of("postcode"));
861	        }
862	        String region = CITY_REGION.get(city);
863	        int[] range = region == null ? null : REGION_POSTCODE_RANGE.get(region);
864	        if (range != null) {
865	            int value = Integer.parseInt(postcode);
866	            if (value < range[0] || value > range[1]) {
867	                throw new InvalidRequestException(List.of("postcode"));
868	            }
869	        }
870	    }
