872	    /**
873	     * Normalize a telephone into E.164 form. Spaces, dashes and brackets are stripped. A value that
874	     * already carries a leading '+' keeps its country code; otherwise the default country code
875	     * ({@code +61}) is assumed and a single leading '0' is dropped from the national digits. The
876	     * result must be a '+' followed by 8 to 15 digits, otherwise an {@link InvalidRequestException}
877	     * is thrown (mapped to 400 Bad Request).
878	     *
879	     * @param telephone the raw telephone from the request payload
880	     * @return the E.164 string (e.g. {@code +61412345678})
881	     */
882	    private String normalizeTelephone(String telephone) {
883	        String cleaned = TELEPHONE_SEPARATORS.matcher(telephone).replaceAll("");
884	        String candidate;
885	        if (cleaned.startsWith("+")) {
886	            candidate = cleaned;
887	        } else {
888	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
889	            candidate = "+" + DEFAULT_COUNTRY_CODE + national;
890	        }
891	        if (!E164_PATTERN.matcher(candidate).matches()) {
892	            throw new InvalidRequestException(List.of("telephone"));
893	        }
894	        // For country codes with a known fixed national-number length, reject a candidate whose
895	        // national digits (everything after the '+' and the country code) do not match that length.
896	        String digits = candidate.substring(1);
897	        for (Map.Entry<String, Integer> entry : COUNTRY_NATIONAL_LENGTH.entrySet()) {
898	            String countryCode = entry.getKey();
899	            if (digits.startsWith(countryCode)) {
900	                int nationalLength = digits.length() - countryCode.length();
901	                if (nationalLength != entry.getValue()) {
902	                    throw new InvalidRequestException(List.of("telephone"));
903	                }
904	                break;
905	            }
906	        }
907	        return candidate;
908	    }
