103	            return OwnerDto.AgeBandEnum.MINOR;
104	        }
105	        if (age < 65) {
106	            return OwnerDto.AgeBandEnum.ADULT;
107	        }
108	        return OwnerDto.AgeBandEnum.SENIOR;
109	    }
110	
111	    /**
112	     * Compute the owner's membership points: starting at 0, add 2 when an email is present, add 1
113	     * when {@code namesakeCount} is 0, add 2 for a household of 3 or more members, and add 3 for a
114	     * tenure of one or more elapsed fiscal years.
115	     */
116	    default int membershipPoints(Owner owner) {
117	        int points = 0;
118	        if (owner.getEmail() != null && !owner.getEmail().isEmpty()) {
119	            points += 2;
120	        }
121	        if (owner.getNamesakeCount() != null && owner.getNamesakeCount() == 0) {
122	            points += 1;
123	        }
124	        if (owner.getHouseholdSize() != null && owner.getHouseholdSize() >= 3) {
125	            points += 2;
126	        }
127	        if (tenureFiscalYears(owner) >= 1) {
