135	     * 3 for 4-5 points and 4 for 6 or more points.
136	     */
137	    default int membershipLevel(int points) {
138	        if (points <= 1) {
139	            return 1;
140	        }
141	        if (points <= 3) {
142	            return 2;
143	        }
144	        if (points <= 5) {
145	            return 3;
146	        }
147	        return 4;
148	    }
