183	            ? owner.getRegistrationDate() : java.time.LocalDate.now();
184	        return String.format("FY%02d", fiscalYear(reference) % 100);
185	    }
186	
187	    /**
188	     * Compute the single Luhn check digit (0-9) over the digits contained in the given value.
189	     * Non-digit characters (such as the hyphens in a customer code) are ignored. A null or
190	     * digit-free value yields a check digit of 0.
191	     */
192	    default Integer luhnCheckDigit(String value) {
193	        if (value == null) {
194	            return 0;
195	        }
196	        int sum = 0;
197	        boolean doubleDigit = true;
198	        for (int i = value.length() - 1; i >= 0; i--) {
199	            char c = value.charAt(i);
200	            if (c < '0' || c > '9') {
201	                continue;
202	            }
203	            int digit = c - '0';
204	            if (doubleDigit) {
205	                digit *= 2;
206	                if (digit > 9) {
207	                    digit -= 9;
208	                }
209	            }
210	            sum += digit;
211	            doubleDigit = !doubleDigit;
212	        }
213	        return (10 - (sum % 10)) % 10;
214	    }
215	
216	    /**
