218	     * telephone into its country code and national digits when building {@code telephoneDisplay}.
219	     * Mirrors the country codes the create endpoint recognises ({@code +61} and {@code +1}).
220	     */
221	    List<String> TELEPHONE_COUNTRY_CODES = List.of("61", "1");
222	
223	    /**
224	     * Format the owner's stored E.164 telephone for humans: the country code, a single space, then
225	     * the national digits grouped in threes (e.g. {@code +61412345678} becomes
226	     * {@code +61 412 345 678}). Returns the raw value unchanged when it is null, not in E.164 form,
227	     * or carries an unrecognised country code.
228	     */
229	    default String deriveTelephoneDisplay(Owner owner) {
230	        String telephone = owner.getTelephone();
231	        if (telephone == null || !telephone.startsWith("+")) {
232	            return telephone;
233	        }
234	        String digits = telephone.substring(1);
235	        String countryCode = null;
236	        for (String code : TELEPHONE_COUNTRY_CODES) {
237	            if (digits.startsWith(code) && digits.length() > code.length()) {
238	                countryCode = code;
239	                break;
240	            }
241	        }
242	        if (countryCode == null) {
243	            return telephone;
244	        }
245	        String national = digits.substring(countryCode.length());
246	        StringBuilder grouped = new StringBuilder();
247	        for (int i = 0; i < national.length(); i++) {
248	            if (i > 0 && i % 3 == 0) {
249	                grouped.append(' ');
250	            }
251	            grouped.append(national.charAt(i));
252	        }
253	        return "+" + countryCode + " " + grouped;
254	    }
255	
256	    /**
257	     * Compose the owner's salutation from its title and last name: the title and last name separated
258	     * by a single space (e.g. {@code DR who}) when a title is present, or just the last name when no
259	     * title (null or blank) was supplied.
260	     */
261	    default String deriveSalutation(Owner owner) {
262	        String lastName = owner.getLastName();
263	        String title = owner.getTitle();
264	        if (title == null || title.isEmpty()) {
