276	    }
277	
278	    /**
279	     * Known metropolitan regions: an owner whose locality is one of these is 'METRO', any other
280	     * locality (including "UNKNOWN") is 'REGIONAL'. Mirrors the pinned city-to-region table.
281	     */
282	    java.util.Set<String> METRO_REGIONS = java.util.Set.of("NSW", "VIC", "QLD");
283	
